CREATE TABLE IF NOT EXISTS departments (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, branch_id uuid REFERENCES branches(id) ON DELETE RESTRICT, code text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS departments_tenant_code_key ON departments(tenant_id, code) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS departments_branch_idx ON departments(tenant_id, branch_id);
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS jobs_tenant_code_key ON jobs(tenant_id, code) WHERE deleted_at IS NULL;
CREATE TABLE IF NOT EXISTS employees (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, employee_no text NOT NULL, name text NOT NULL, branch_id uuid REFERENCES branches(id) ON DELETE RESTRICT, department_id uuid REFERENCES departments(id) ON DELETE SET NULL, job_id uuid REFERENCES jobs(id) ON DELETE SET NULL, membership_id uuid REFERENCES memberships(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','terminated')), hire_date date, salary_components jsonb NOT NULL DEFAULT '{}', bank jsonb NOT NULL DEFAULT '{}', salary_expense_account_id uuid REFERENCES accounts(id) ON DELETE RESTRICT, salary_payable_account_id uuid REFERENCES accounts(id) ON DELETE RESTRICT, cost_center_id uuid REFERENCES cost_centers(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, deleted_at timestamptz, deleted_by uuid, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS employees_tenant_no_key ON employees(tenant_id, employee_no) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS employees_branch_idx ON employees(tenant_id, branch_id);
CREATE INDEX IF NOT EXISTS employees_membership_idx ON employees(tenant_id, membership_id);
CREATE TABLE IF NOT EXISTS attendance_logs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, employee_id uuid REFERENCES employees(id) ON DELETE CASCADE, machine text NOT NULL, enroll text NOT NULL, punch_at timestamptz NOT NULL, direction text NOT NULL CHECK (direction IN ('in','out','unknown')), fingerprint text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS attendance_logs_fingerprint_key ON attendance_logs(tenant_id, fingerprint);
CREATE INDEX IF NOT EXISTS attendance_logs_employee_idx ON attendance_logs(tenant_id, employee_id, punch_at);
CREATE INDEX IF NOT EXISTS attendance_logs_enroll_idx ON attendance_logs(tenant_id, enroll, punch_at);
CREATE TABLE IF NOT EXISTS salary_adjustments (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, employee_id uuid NOT NULL REFERENCES employees(id) ON DELETE CASCADE, kind text NOT NULL CHECK (kind IN ('addition','deduction')), component_code text NOT NULL, value_text numeric(20,4) NOT NULL, starts_on date NOT NULL, ends_on date, recurring boolean NOT NULL DEFAULT false, sub_from_salary boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','approved','voided')), cash_location_id uuid REFERENCES cash_locations(id) ON DELETE SET NULL, journal_entry_id uuid REFERENCES journal_entries(id) ON DELETE SET NULL, reason text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, legacy_source text, legacy_id text);
CREATE INDEX IF NOT EXISTS salary_adjustments_employee_idx ON salary_adjustments(tenant_id, employee_id, starts_on);
CREATE INDEX IF NOT EXISTS salary_adjustments_status_idx ON salary_adjustments(tenant_id, status);
CREATE TABLE IF NOT EXISTS payroll_runs (id uuid PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, period_id uuid REFERENCES fiscal_periods(id) ON DELETE RESTRICT, year_month text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','posted','paid','reversed')), currency text NOT NULL DEFAULT 'SAR', summary jsonb NOT NULL DEFAULT '{}', journal_entry_id uuid REFERENCES journal_entries(id) ON DELETE SET NULL, voucher_id uuid REFERENCES vouchers(id) ON DELETE SET NULL, posted_at timestamptz, paid_at timestamptz, reversed_at timestamptz, reversal_reason text, created_at timestamptz NOT NULL DEFAULT now(), created_by uuid, updated_at timestamptz, updated_by uuid, version int NOT NULL DEFAULT 1, legacy_source text, legacy_id text);
CREATE UNIQUE INDEX IF NOT EXISTS payroll_runs_month_key ON payroll_runs(tenant_id, year_month) WHERE status <> 'reversed';
CREATE INDEX IF NOT EXISTS payroll_runs_status_idx ON payroll_runs(tenant_id, status);
CREATE TABLE IF NOT EXISTS payroll_run_lines (run_id uuid NOT NULL REFERENCES payroll_runs(id) ON DELETE CASCADE, line_no int NOT NULL, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, employee_id uuid NOT NULL REFERENCES employees(id) ON DELETE RESTRICT, components jsonb NOT NULL DEFAULT '{}', additions numeric(20,4) NOT NULL DEFAULT 0, deductions numeric(20,4) NOT NULL DEFAULT 0, gross numeric(20,4) NOT NULL, net numeric(20,4) NOT NULL, cost_center_id uuid REFERENCES cost_centers(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'draft', payslip_html text, PRIMARY KEY(run_id, line_no));
CREATE INDEX IF NOT EXISTS payroll_run_lines_employee_idx ON payroll_run_lines(tenant_id, employee_id);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['departments','jobs','employees','attendance_logs','salary_adjustments','payroll_runs','payroll_run_lines'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t); EXECUTE format('DROP POLICY IF EXISTS %I_tenant_isolation ON %I', t, t); EXECUTE format('CREATE POLICY %I_tenant_isolation ON %I USING (tenant_id = current_setting(''app.tenant_id'', true)::uuid) WITH CHECK (tenant_id = current_setting(''app.tenant_id'', true)::uuid)', t, t); END LOOP; END $$;
